// Validates the Draft-07 subset used by catalog.schema.json, without a runtime dependency.
export function validateSchema(value,schema,path='$'){
 const supported=new Set(['$schema','type','required','additionalProperties','properties','enum','minimum','maximum','exclusiveMinimum','minLength','pattern','minItems','maxItems','items']);for(const key of Object.keys(schema))if(!supported.has(key))throw TypeError(`Unsupported schema keyword at ${path}: ${key}`);
 const fail=message=>{throw TypeError(`${path}: ${message}`);};
 const type=schema.type;
 if(type&&!(type==='object'?value!==null&&typeof value==='object'&&!Array.isArray(value):type==='array'?Array.isArray(value):type==='integer'?Number.isSafeInteger(value):type==='number'?typeof value==='number'&&Number.isFinite(value):typeof value===type))fail(`expected ${type}`);
 if(schema.enum&&!schema.enum.includes(value))fail('not in enum');
 if(typeof value==='number'){if(schema.minimum!==undefined&&value<schema.minimum)fail('below minimum');if(schema.maximum!==undefined&&value>schema.maximum)fail('above maximum');if(schema.exclusiveMinimum!==undefined&&value<=schema.exclusiveMinimum)fail('below exclusive minimum');}
 if(typeof value==='string'){if(schema.minLength!==undefined&&value.length<schema.minLength)fail('empty string');if(schema.pattern&&!new RegExp(schema.pattern).test(value))fail('invalid pattern');}
 if(Array.isArray(value)){if(schema.minItems!==undefined&&value.length<schema.minItems)fail('too few items');if(schema.maxItems!==undefined&&value.length>schema.maxItems)fail('too many items');if(schema.items)value.forEach((v,i)=>validateSchema(v,schema.items,`${path}[${i}]`));}
 else if(value&&typeof value==='object'){for(const key of schema.required??[])if(!Object.hasOwn(value,key))fail(`missing ${key}`);for(const [key,v] of Object.entries(value)){const sub=schema.properties?.[key];if(sub)validateSchema(v,sub,`${path}.${key}`);else if(schema.additionalProperties===false)fail(`unknown property ${key}`);else if(typeof schema.additionalProperties==='object')validateSchema(v,schema.additionalProperties,`${path}.${key}`);}}
 return value;
}
export async function loadJSON(relative){const url=new URL(relative,import.meta.url);if(globalThis.process?.versions?.node){const {readFile}=await import('node:fs/promises');return JSON.parse(await readFile(url,'utf8'));}const response=await fetch(url,{cache:'no-cache',signal:AbortSignal.timeout(15000)});if(!response.ok)throw Error(`Catalog ${relative}: HTTP ${response.status}`);return response.json();}
export function validateReferences(c){
 const index=key=>{const out=new Map();for(const d of c[key]){if(out.has(d.id))throw TypeError(`Duplicate ${key} ID: ${d.id}`);out.set(d.id,d);}return out;};
 const commodities=index('commodities'),assets=index('assets'),factions=index('factions'),banks=index('naming');index('settlements');index('industries');index('vessels');const docks=index('docks');const buildings=index('town_buildings');index('roads');
 const presets=index('colony_presets');
 const ref=(map,id,label)=>{if(!map.has(id))throw TypeError(`Unknown ${label}: ${id}`);};
 const unique=(values,label)=>{if(new Set(values).size!==values.length)throw TypeError(`Duplicate ${label}`);};
 unique(c.factions.map(f=>f.runtime_id),'runtime faction');unique(c.factions.map(f=>f.harbor_frame),'harbor frame');unique(c.vessels.map(v=>v.type),'vessel type');
 const runtimes=new Set(c.factions.map(f=>f.runtime_id));
 for(const f of factions.values()){ref(banks,f.naming_bank_ref,'name bank');ref(assets,f.flag_asset,'flag');if(f.faction_id!==f.id)throw TypeError('Faction ID mismatch');for(const id of Object.keys(f.base_relations))if(!runtimes.has(id))throw TypeError('Unknown relation faction');}
 for(const v of c.vessels){if(v.ship_class_id!==v.type||v.cargo_capacity!==v.physics.cargoCapacity||v.base_speed!==v.physics.maxSpeed||v.baseHullMaintenance!==v.base_hull_maintenance_per_day||v.crewCapacity!==v.crew_complement.max_crew||v.crew_complement.min_crew>v.crewCapacity||v.defaultCrew>v.crewCapacity)throw TypeError(`Inconsistent vessel: ${v.id}`);if(v.militaryOnly!==(v.category==='Military')||v.canTrade===v.militaryOnly)throw TypeError('Invalid vessel trading role');if(v.required_berth_size!==v.physics.required_berth_size)throw TypeError('Inconsistent berth size');ref(assets,v.graphics.sprite_asset,'sprite');ref(assets,v.graphics.icon_asset,'icon');if(v.graphics.anchors.length!==v.graphics.frames||v.graphics.sail_frame_weights.length!==5||v.graphics.sail_frame_weights.some(weights=>weights.length!==5||!weights.some(w=>w>0)))throw TypeError('Invalid sail graphics');}
 for(const i of c.industries){validateManufacturingDefinition(i,commodities.keys());if(i.industry_id!==i.id)throw TypeError('Industry ID mismatch');for(const list of [i.inputs,i.outputs]){unique(list.map(x=>x.commodity_id),'recipe commodity');for(const x of list)ref(commodities,x.commodity_id,'recipe commodity');}for(const id of Object.keys(i.base_build_cost))ref(commodities,id,'construction commodity');ref(assets,i.graphics.tile_asset,'industry graphic');ref(assets,i.graphics.icon_asset,'industry icon');const tile=assets.get(i.graphics.tile_asset);if(tile.kind!=='atlas'||!tile.columns||tile.rows!==1||!Number.isSafeInteger(i.graphics.atlas_frame)||i.graphics.atlas_frame<0||i.graphics.atlas_frame>=tile.columns)throw TypeError('Invalid industry tile frame');const icon=c.assets.find(a=>a.id===i.graphics.icon_asset);if(icon.kind!=='atlas'||!icon.columns||!icon.rows||i.graphics.icon_frame>=icon.columns*icon.rows)throw TypeError('Invalid industry icon frame');if(i.placement.enabled&&i.placement.code!==i.graphics.atlas_frame+1)throw TypeError('Industry placement/graphic frame mismatch');}
 for(const d of docks.values()){
  if(d.id!==d.dock_type_id||d.layout.side_slots!==d.max_simultaneous_ships)throw TypeError('Inconsistent dock layout');for(const id of Object.keys(d.build_cost))ref(commodities,id,'dock material');
  if(d.layout.length_tiles>1&&!d.graphics.tip_rotations)throw TypeError('Missing dock tip views');
  for(const views of [d.graphics.rotations,d.graphics.tip_rotations].filter(Boolean))for(const [angle,rotation] of Object.entries(views)){
   if(!['0','60','120','180','240','300'].includes(angle))throw TypeError('Invalid dock rotation');ref(assets,rotation.asset_id,'dock rotation');const asset=assets.get(rotation.asset_id);if(!asset.columns||!asset.rows)throw TypeError('Missing dock atlas layout');if(!asset.tile_radius)throw TypeError('Missing dock hex pixel radius');if(!Number.isSafeInteger(rotation.atlas_frame)||rotation.atlas_frame<0||rotation.atlas_frame>=asset.columns*asset.rows)throw TypeError('Invalid dock graphic frame');
  }
 }
 for(const s of c.settlements){ref(buildings,s.urban_growth.housing_type,'urban housing');if(buildings.get(s.urban_growth.housing_type).housing_capacity<=0)throw TypeError('Housing must add capacity');ref(docks,s.initial_dock_type,'initial dock');for(const type of s.initial_dock_mix??[])ref(docks,type,'initial dock mix');ref(assets,s.graphics.dock_asset,'dock');ref(assets,s.graphics.harbor_asset,'harbor');for(const id of [s.graphics.dock_asset,s.graphics.harbor_asset]){const asset=assets.get(id);if(!asset.columns||!asset.rows)throw TypeError('Missing atlas layout: '+id);}const harbor=assets.get(s.graphics.harbor_asset);if(c.factions.some(f=>!Number.isSafeInteger(f.harbor_frame)||f.harbor_frame<0||f.harbor_frame>=harbor.columns*harbor.rows))throw TypeError('Faction frame outside harbor atlas');}
 for(const asset of assets.values())if(asset.atlas_frame!==undefined&&(!asset.columns||!asset.rows||asset.atlas_frame>=asset.columns*asset.rows))throw TypeError('Invalid asset atlas frame');
 for(const b of buildings.values()){b.renovation_multiplier??=0.3;if(b.id!==b.building_type_id)throw TypeError('Building ID mismatch');for(const id of Object.keys(b.build_cost))ref(commodities,id,'building material');for(const id of [...b.variants,b.derelict_variant]){ref(assets,id,'building graphic');if(assets.get(id).flag_policy!=='none')throw TypeError('Town artwork must be faction neutral and flag free');}}
 for(const p of presets.values()){if(p.id!==p.colony_preset_id)throw TypeError('Preset ID mismatch');for(const d of p.tile_layout.docks)ref(docks,d.type,'preset dock');for(const t of p.tile_layout.town_tiles)ref(buildings,t.building,'preset building');}
 for(const road of c.roads){ref(assets,road.asset_id,'road graphic');if(road.kind==='urban_infill'?road.mask!==0:road.mask===0)throw TypeError('Invalid road mask');}
 return c;
}
export async function loadCatalogs(){if(!globalThis.process?.versions?.node){const catalog=structuredClone(compiledCatalog),schema=structuredClone(compiledSchema);validateSchema(catalog,schema);validateReferences(catalog);return {catalog,schema};}const keys=['commodities','vessels','industries','assets','factions','naming','settlements','settings','docks','town_buildings','roads','colony_presets','configuration_definitions','configuration_overrides','configuration_constraints'];const [schema,...values]=await Promise.all([loadJSON('./data/catalog.schema.json'),...keys.map(k=>loadJSON(`./data/${k}.json`))]);const catalog=Object.fromEntries(keys.map((k,i)=>[k,values[i]]));validateSchema(catalog,schema);validateReferences(catalog);return {catalog,schema};}
